using Microsoft.Extensions.Options;

public class ApiSettingsValidator : IValidateOptions<ApiSettings>
{
    public ValidateOptionsResult Validate(
        string? name, ApiSettings options)
    {
        var errors = new List<string>();

        if (string.IsNullOrWhiteSpace(options.BaseUrl))
            errors.Add("ApiSettings:BaseUrl is required.");

        if (options.TimeoutSeconds is < 1 or > 120)
            errors.Add("ApiSettings:TimeoutSeconds must be between 1 and 120.");

        return errors.Count == 0
            ? ValidateOptionsResult.Success
            : ValidateOptionsResult.Fail(errors);
    }
}

// Register the validator in Program.cs
builder.Services.AddSingleton<IValidateOptions<ApiSettings>, ApiSettingsValidator>();

// Program.cs — register each named section
builder.Services.Configure<ApiSettings>(
    "Weather",
    builder.Configuration.GetSection("ExternalApis:Weather"));
builder.Services.Configure<ApiSettings>(
    "Geocoding",
    builder.Configuration.GetSection("ExternalApis:Geocoding"));

// Controller — retrieve a named options instance
public class ExternalApiController : Controller
{
    private readonly ApiSettings _weatherSettings;
    private readonly ApiSettings _geoCodingSettings;

    public ExternalApiController(IOptionsMonitor<ApiSettings> monitor)
    {
        _weatherSettings  = monitor.Get("Weather");
        _geoCodingSettings = monitor.Get("Geocoding");
    }
}
